package com.gameaggregator.gameservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="game_taxonomies",uniqueConstraints=@UniqueConstraint(columnNames={"gameId","taxonomyId"})) public class GameTaxonomy{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID gameId;@Column(nullable=false)public UUID taxonomyId;protected GameTaxonomy(){}public GameTaxonomy(UUID g,UUID t){gameId=g;taxonomyId=t;}}